fun insert(record: ByteArray): Int? {
    if (record.size > MAX_RECORD) throw RecordTooLargeException(record.size)
    val need = record.size + SLOT_SIZE
    if (freeSpace() < need) {
        val live = (0 until slotCount()).sumOf { slotLength(it) }
        if (PAGE_SIZE - lower - live < need) return null   // even compaction can't help
        compact()
    }
    upper -= record.size                 // rows grow down from the end
    buf.put(upper, record)
    val slot = slotCount()               // new slots always go at the end of the array
    setSlot(slot, upper, record.size)
    lower += SLOT_SIZE
    return slot
}

fun compact() {
    var top = PAGE_SIZE
    for (s in (0 until slotCount()).filter { slotLength(it) > 0 }.sortedByDescending { slotOffset(it) }) {
        top -= slotLength(s)
        System.arraycopy(buf.array(), slotOffset(s), buf.array(), top, slotLength(s))
        setSlot(s, top, slotLength(s))   // same slot id, new offset
    }
    upper = top
}
